#!/usr/bin/env node
// Writes addons/Spoken_Places/Data/Languages.lua: what each language covers, and
// whether it is finished enough to offer to players.
//
//   node tools/locale/build-languages.mjs
//
// A language is not something the addon can measure at runtime. It can count the
// lore entries it loaded, but not how many there were supposed to be, and it
// cannot see a translation it did not load at all. So coverage is counted here,
// against English, and the answer is baked into a generated file.
//
// READY MEANS THE LORE IS COMPLETE. A language appears in the switcher when every
// line has a translation and -- for a language that is not English -- when it has
// an alias table, without which its client would match no subzone at all. The
// interface strings are NOT required: they fall back to English per key, and an
// English options panel over a German lore corpus is a language worth shipping.
// Audio is reported but not required either: a fully translated, silent language
// is worth reading. Both are still counted, so what is missing stays visible.
//
// Regenerate after translating anything. `make check` reports what this would
// write, so a stale file is visible rather than quietly under-reporting.

import { readdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";

import { BASE_LOCALE, isClientLocale, LOCALES } from "../lib/locales.mjs";
import { luaString, ROOT } from "../lib/wiki.mjs";
import { stringCoverage } from "./check-strings.mjs";
import { loadPacks } from "../../../../scripts/lib/packs.mjs";

// A Windows checkout has CRLF on disk; the counts and the --check compare lines as Git stores them.
const read = async (path) => (await readFile(path, "utf8")).replace(/\r\n/g, "\n");

const DATA = join(ROOT, "addons/Spoken_Places/Data");
const OUT_PATH = join(DATA, "Languages.lua");

// Whether a language has a pack: its page under publishers/places/ is what says so, since a
// page is what the release scripts upload from. Not whether the masters are on this disk.
const AUDIO_PUBLISHED = new Set(
  loadPacks().filter((pack) => pack.section === "places").map((pack) => pack.lang),
);

// Pending entries are places the client can name that nobody has written, in any
// language. Counting them would say English is complete when 96 of its lines are empty,
// and would hand every other language a target it cannot translate: there is nothing
// there to translate. They are not lore yet, so they are not lore here.
//
// The marker leads its entry, so it is the line after the `[key] = {` that opens one.
function countEntries(src, openRe) {
  const lines = src.split("\n");
  let count = 0;
  for (let i = 0; i < lines.length; i++) {
    if (!openRe.test(lines[i])) continue;
    if (/^\t+pending = true,$/.test(lines[i + 1] ?? "")) continue;
    count++;
  }
  return count;
}

async function countLore(lang) {
  const zones = await read(join(DATA, lang, "Zones.lua")).catch(() => null);
  if (zones === null) return { zones: 0, subzones: 0 };
  const subzones = await read(join(DATA, lang, "Subzones.lua")).catch(() => "");
  return {
    zones: countEntries(zones, /^\t\[\d+\] = \{$/),
    subzones: countEntries(subzones, /^\t\t\[".*"\] = \{$/),
  };
}

async function countAliases(lang) {
  const src = await read(join(DATA, lang, "Aliases.lua")).catch(() => null);
  if (src === null) return 0;
  return (src.match(/^\t\[".*"\] = ".*",$/gm) || []).length;
}

export async function buildLanguages() {
  const strings = await stringCoverage();
  const base = await countLore(BASE_LOCALE);
  const baseTotal = base.zones + base.subzones;
  if (baseTotal === 0) throw new Error("no English corpus: nothing to measure against");

  const rows = [];
  for (const locale of LOCALES) {
    const lore = await countLore(locale.code);
    const loreDone = lore.zones + lore.subzones;
    const aliases = await countAliases(locale.code);
    const strung = strings.get(locale.code) || { done: 0, total: 0 };

    // Aliases turn what a client shows into English keys, so only a language a client runs in
    // needs them; one no client ships (Italian) is ready once its lore is.
    const needsAliases = locale.code !== BASE_LOCALE && isClientLocale(locale.code);
    const ready = loreDone === baseTotal && (!needsAliases || aliases > 0);

    rows.push({ locale, loreDone, strung, aliases, ready });
  }

  const lines = [
    "-- AUTO-GENERATED by tools/locale/build-languages.mjs. Do not edit by hand.",
    "--",
    "-- What each language covers, and whether it is finished. `ready` is what",
    "-- decides whether a language is offered in the switcher at all: every lore",
    "-- line translated, and an alias table where a client runs in the language.",
    "-- Interface strings and audio are counted but not required; strings fall",
    "-- back to English per key.",
    "--",
    `-- Measured against English: ${baseTotal} lore lines, ${strings.get(BASE_LOCALE).total} interface strings.`,
    "",
    "local _, SpokenPlaces = ...",
    "",
    "SpokenPlaces.Languages = {",
  ];

  for (const row of rows) {
    lines.push(
      `\t{ code = ${luaString(row.locale.code)}, ` +
        `lore = { done = ${row.loreDone}, total = ${baseTotal} }, ` +
        `strings = { done = ${row.strung.done}, total = ${row.strung.total} }, ` +
        `aliases = ${row.aliases}, ` +
        `audio = ${AUDIO_PUBLISHED.has(row.locale.code)}, ` +
        `ready = ${row.ready} },`,
    );
  }

  lines.push("}", "");
  return { text: lines.join("\n"), rows, baseTotal };
}

async function main() {
  const { text, rows } = await buildLanguages();

  const onDisk = await read(OUT_PATH).catch(() => null);
  if (process.argv.includes("--check")) {
    if (onDisk !== text) {
      console.error(`out of date: ${OUT_PATH}`);
      console.error("regenerate with:  make languages");
      process.exitCode = 1;
      return;
    }
    console.log(`up to date -- ${rows.filter((r) => r.ready).length} language(s) ready`);
    return;
  }

  await writeFile(OUT_PATH, text);
  console.log(`wrote ${OUT_PATH}`);
  for (const row of rows) {
    const state = row.ready ? "ready" : "not ready";
    console.log(
      `  ${row.locale.code}: ${row.loreDone} lore, ${row.strung.done} strings, ` +
        `${row.aliases} aliases -- ${state}`,
    );
  }
}

if (process.argv[1] && process.argv[1].endsWith("build-languages.mjs")) {
  main().catch((err) => {
    console.error(err);
    process.exitCode = 1;
  });
}
